validator:
function validate(input) {
  const [{ employees = [] }] = input;
  for (const [, salary] of employees) {
    if (salary === null) return 'salary cannot be null.';
    if (salary < 0) return 'salary cannot be negative.';
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const names = ['Jack', 'Piper', 'Mia', 'Ulysses', 'Ivy', 'Leo', 'Nora', 'Owen'];
  const pay = [0, 1, 2, 19666, 54866, 62509, 74754];
  const rows = size === 'small' ? Math.floor(rand() * 9) : 2000;
  const employees = [];
  for (let i = 0; i < rows; i++) {
    const salary = size === 'small' && rand() < 0.6 ? pick(pay) : Math.floor(rand() * 200000);
    employees.push([size === 'small' ? pick(names) : `${pick(names)}${i}`, salary]);
  }
  return [{ employees }];
}
